**Problem 7:**

Implement a simple banking system using Python classes and objects.

```python
class BankAccount:
    def __init__(self, account_number, account_holder, initial_balance):
        self.account_number = account_number
        self.account_holder = account_holder
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposited ${amount:.2f}. New balance: ${self.balance:.2f}")
        else:
            print("Invalid deposit amount.")

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            print(f"Withdrew ${amount:.2f}. New balance: ${self.balance:.2f}")
        elif amount <= 0:
            print("Invalid withdrawal amount.")
        else:
            print("Insufficient funds.")

    def check_balance(self):
        print(f"Current balance: ${self.balance:.2f}")


class Bank:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_number, account_holder, initial_balance):
        if account_number not in self.accounts:
            self.accounts[account_number] = BankAccount(account_number, account_holder, initial_balance)
            print(f"Account created for {account_holder}.")
        else:
            print("Account number already exists.")

    def get_account(self, account_number):
        return self.accounts.get(account_number)

    def display_accounts(self):
        for account in self.accounts.values():
            print(f"Account Number: {account.account_number}")
            account.check_balance()
            print()


# Example usage
bank = Bank()

while True:
    print("\n1. Create Account")
    print("2. Deposit")
