        bank.create_account(account_number, account_holder, initial_balance)
    elif choice == "2":
        account_number = input("Enter account number: ")
        amount = float(input("Enter deposit amount: "))
        bank.get_account(account_number).deposit(amount)
    elif choice == "3":
        account_number = input("Enter account number: ")
        amount = float(input("Enter withdrawal amount: "))
        bank.get_account(account_number).withdraw(amount)
    elif choice == "4":
        account_number = input("Enter account number: ")
        bank.get_account(account_number).check_balance()
    elif choice == "5":
        bank.display_accounts()
    elif choice == "6":
        break
    else:
        print("Invalid option. Please choose again.")
